/*
 * prog59_rule110.c
 *
 * Re‑implementation of the original binary (prog59_rule110) after reverse‑engineering.
 * The program expects exactly two command‑line arguments:
 *
 *   1. A binary string consisting only of the characters ‘0’ and ‘1’.
 *      Its length must be between 1 and 60 (inclusive).
 *   2. A non‑negative integer N (the number of rows to output).
 *
 * The program prints the supplied string as the first row and then prints N‑1
 * further rows generated by elementary cellular automaton Rule 110.
 * Each row is terminated by a newline.  If any validation fails the program
 * prints the literal string "INVALID_INPUT" (followed by a newline) and exits.
 *
 * The original binary limited the number of rows to 200; this implementation
 * follows the same limit.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN 60          /* maximum length of the input string   */
#define MAX_STEPS 200       /* maximum number of rows to output     */

/* Rule 110 lookup table.
 * Index is (left<<2) | (center<<1) | right   (bits are 0/1).
 * The value is the next state (0 or 1).
 *
 * 111 -> 0
 * 110 -> 1
 * 101 -> 1
 * 100 -> 0
 * 011 -> 1
 * 010 -> 1
 * 001 -> 1
 * 000 -> 0
 */
static const char rule110[8] = {
    /* 000 */ '0',
    /* 001 */ '1',
    /* 010 */ '1',
    /* 011 */ '1',
    /* 100 */ '0',
    /* 101 */ '1',
    /* 110 */ '1',
    /* 111 */ '0'
};

/* Validate that a string consists only of ‘0’ and ‘1’. */
static int is_binary_string(const char *s, size_t len)
{
    for (size_t i = 0; i < len; ++i)
        if (s[i] != '0' && s[i] != '1')
            return 0;
    return 1;
}

/* Compute the next generation of a Rule‑110 automaton. */
static void next_rule110(const char *cur, char *next, size_t len)
{
    for (size_t i = 0; i < len; ++i) {
        int left   = (i == 0) ? 0 : (cur[i - 1] - '0');
        int center = cur[i] - '0';
        int right  = (i == len - 1) ? 0 : (cur[i + 1] - '0');

        int idx = (left << 2) | (center << 1) | right;
        next[i] = rule110[idx];
    }
}

/* Print a row (without a terminating newline). */
static void print_row(const char *row, size_t len)
{
    for (size_t i = 0; i < len; ++i)
        putchar(row[i]);
    putchar('\n');
}

int main(int argc, char **argv)
{
    /* ----- argument count check ----- */
    if (argc != 3) {
        puts("INVALID_INPUT");
        return 0;
    }

    /* ----- first argument: binary string ----- */
    const char *input = argv[1];
    size_t len = strlen(input);

    if (len == 0 || len > MAX_LEN || !is_binary_string(input, len)) {
        puts("INVALID_INPUT");
        return 0;
    }

    /* ----- second argument: number of rows ----- */
    char *endptr;
    long steps = strtol(argv[2], &endptr, 10);

    if (endptr == argv[2] || *endptr != '\0' || steps < 0) {
        puts("INVALID_INPUT");
        return 0;
    }

    if (steps > MAX_STEPS)
        steps = MAX_STEPS;          /* the original binary caps the value */

    /* ----- allocate buffers for two rows ----- */
    char *curr = malloc(len + 1);
    char *next = malloc(len + 1);
    if (!curr || !next) {
        puts("INVALID_INPUT");
        free(curr);
        free(next);
        return 0;
    }

    memcpy(curr, input, len);
    curr[len] = '\0';

    /* ----- output the required rows ----- */
    for (long row = 0; row < steps; ++row) {
        print_row(curr, len);
        if (row == steps - 1)
            break;                     /* no need to compute a next row */
        next_rule110(curr, next, len);
        next[len] = '\0';
        char *tmp = curr;
        curr = next;
        next = tmp;
    }

    free(curr);
    free(next);
    return 0;
}
